rules.implementation:
n = value["EchoTime"].dropna().nunique()
exact = params.get("exact_echoes")
if exact is not None:
    if n != exact:
        raise ValidationError(f"Expected exactly {exact} echoes, found {n}.")
else:
    min_n = params.get("min_echoes")
    if min_n is not None and n < min_n:
        raise ValidationError(f"Only {n} echoes; at least {min_n} required.")
    rec = params.get("recommended_echoes")
    if rec is not None and n < rec:
        raise ValidationWarning(f"Found {n} echoes; {rec}+ recommended.")

echo_times = value["EchoTime"].dropna().sort_values()
field_strength = value["MagneticFieldStrength"].iloc[0]

tissue_values = {
    1.5: {"grey": 84.0, "white": 66.2, "caudate": 58.8, "putamen": 55.5},
    3.0: {"grey": 66.0, "white": 53.2, "caudate": 41.3, "putamen": 31.5},
    7.0: {"grey": 33.2, "white": 26.8, "caudate": 19.9, "putamen": 16.1},
}

max_tissue = max(tissue_values[field_strength].values())
min_tissue = min(tissue_values[field_strength].values())

if echo_times.iloc[-1] > 1.25 * max_tissue:
    raise ValidationError(f"The longest TE should be ≤1.25x the highest tissue T2* ({max_tissue} ms).")
if echo_times.iloc[-1] < 0.75 * min_tissue:
    raise ValidationError(f"The longest TE should be ≥0.75x the lowest tissue T2* ({min_tissue} ms).")

# Validate magnitude/phase pairs per echo
for echo_time, group in value.groupby("EchoTime"):
    image_types = group["ImageType"]

    # ImageType is list-valued; check components, not the string repr
    has_magnitude = any("M" in as_list(it) for it in image_types)
    has_phase = any("P" in as_list(it) for it in image_types)

    if not has_magnitude:
        raise ValidationError(f"Echo time {echo_time} ms is missing magnitude image.")

    if not has_phase:
        raise ValidationError(f"Echo time {echo_time} ms is missing phase image.")

num_slices = value['Count']
if not all(num_slices == num_slices.iloc[0]):
    raise ValidationError(f"Magnitude and phase images do not have the same number of slices. Found {list(num_slices)}.")

pixel_bandwidth = value["PixelBandwidth"].iloc[0]
field_strength = value["MagneticFieldStrength"].iloc[0]
max_bw = params.get("max_bandwidth_hz_px")
ref_field = params.get("reference_field_t")
if ref_field is not None and field_strength != ref_field:
    if params.get("warn_at_other_field"):
        raise ValidationWarning(f"PixelBandwidth recommendations are not available at {field_strength}T (defined at {ref_field:g}T).")
elif max_bw is not None and pixel_bandwidth > max_bw:
    at_field = f" at {ref_field:g}T" if ref_field is not None else ""
    raise ValidationError(f"PixelBandwidth should be <= {max_bw:g} Hz/pixel{at_field}. Found {pixel_bandwidth} Hz/pixel.")
